{
  "hypotheses": [
    {
      "text": "The RevenueFromContractWithCustomerExcludingAssessedTax concept was introduced after IBM's earlier filings, so IBM's historic XBRL submissions do not contain this element.",
      "how_to_test": "SELECT MIN(fiscal_year) AS first_year, MAX(fiscal_year) AS last_year FROM edgar.revenue_facts WHERE cik = 51143 AND concept = 'RevenueFromContractWithCustomerExcludingAssessedTax';"
    },
    {
      "text": "IBM reports all revenue under the generic 'Revenues' concept and does not disaggregate revenue by contract under ASC 606, so there are no non‑zero facts for the more specific concept.",
      "how_to_test": "SELECT SUM(value_usd) AS total_rev FROM edgar.revenue_facts WHERE cik = 51143 AND concept = 'Revenues';"
    },
    {
      "text": "IBM's XBRL filings omit zero‑value facts; the RevenueFromContractWithCustomerExcludingAssessedTax element exists but its value is zero, so no row appears in the facts table.",
      "how_to_test": "SELECT COUNT(*) AS zero_rows FROM edgar.revenue_facts WHERE cik = 51143 AND concept = 'RevenueFromContractWithCustomerExcludingAssessedTax' AND value_usd = 0;"
    },
    {
      "text": "A reference‑data gap causes the concept label to be mismatched (e.g., IBM uses a variant such as 'RevenueFromContractsWithCustomer' ), so the exact string we filter on never matches IBM's facts.",
      "how_to_test": "SELECT DISTINCT concept FROM edgar.revenue_facts WHERE cik = 51143 AND concept LIKE '%RevenueFromContract%';"
    }
  ]
}
